package com.example.english_app;
import android.app.Activity;import android.content.Intent;import android.os.Bundle;import android.view.View;import android.view.animation.DecelerateInterpolator;
public class LessonDetailActivity extends Activity{
@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_lesson_detail);findViewById(R.id.lessonBack).setOnClickListener(v->finish());findViewById(R.id.startLesson).setOnClickListener(v->startActivity(new Intent(this,VocabularyActivity.class)));int[] ids={R.id.lessonBack,R.id.lessonBadge,R.id.lessonTitle,R.id.lessonObjective,R.id.lessonWords,R.id.startLesson};boolean reduce=android.provider.Settings.Global.getFloat(getContentResolver(),android.provider.Settings.Global.ANIMATOR_DURATION_SCALE,1f)==0f;if(!reduce)for(int i=0;i<ids.length;i++){View v=findViewById(ids[i]);v.setAlpha(0f);v.setTranslationY(20f*getResources().getDisplayMetrics().density);v.animate().alpha(1f).translationY(0).setStartDelay(i*130L).setDuration(350).setInterpolator(new DecelerateInterpolator()).start();}}}
